// CaptureRollbackState is side-effect free and includes transient and
// sync-only fields. Persistence changes live in RollbackTx, not in the DAO.
func (d *PlayerDao) CaptureRollbackState() ([]byte, error) {
	type rollbackDoc struct {
		Id             int64            `bson:"_id"`
		Name           string           `bson:"name"`
		Level          int32            `bson:"level"`
		Exp            int64            `bson:"exp"`
		Gold           int64            `bson:"gold"`
		Items          map[int64]int32  `bson:"items"`
		PosX           int64            `bson:"pos_x"`
		PosY           int64            `bson:"pos_y"`
		SceneID        int64            `bson:"scene_id"`
		Equipment      equipmentBSONDoc `bson:"equipment"`
		AttrBase       map[int32]int64  `bson:"attr_base"`
		AttrFinal      map[int32]int64  `bson:"attr_final"`
		DungeonClaims  map[string]int64 `bson:"dungeon_claims"`
		MailClaims     map[string]int64 `bson:"mail_claims"`
		PurchaseClaims map[string]int64 `bson:"purchase_claims"`
		GuildID        int64            `bson:"guild_id"`
	}
	doc := rollbackDoc{
		Id:             d.id,
		Name:           d.name,
		Level:          d.level,
		Exp:            d.exp,
		Gold:           d.gold,
		Items:          d.playerDaoItemsRawMap(),
		PosX:           d.posX,
		PosY:           d.posY,
		SceneID:        d.sceneID,
		Equipment:      d.equipment.bsonDoc(),
		AttrBase:       d.playerDaoAttrBaseRawMap(),
		AttrFinal:      d.playerDaoAttrFinalRawMap(),
		DungeonClaims:  d.playerDaoDungeonClaimsRawMap(),
		MailClaims:     d.playerDaoMailClaimsRawMap(),
		PurchaseClaims: d.playerDaoPurchaseClaimsRawMap(),
		GuildID:        d.guildID,
	}
	return bson.Marshal(doc)
}

func (d *PlayerDao) RestoreRollbackState(raw []byte) error {
	type rollbackDoc struct {
		Id             int64            `bson:"_id"`
		Name           string           `bson:"name"`
		Level          int32            `bson:"level"`
		Exp            int64            `bson:"exp"`
		Gold           int64            `bson:"gold"`
		Items          map[int64]int32  `bson:"items"`
		PosX           int64            `bson:"pos_x"`
		PosY           int64            `bson:"pos_y"`
		SceneID        int64            `bson:"scene_id"`
		Equipment      equipmentBSONDoc `bson:"equipment"`
		AttrBase       map[int32]int64  `bson:"attr_base"`
		AttrFinal      map[int32]int64  `bson:"attr_final"`
		DungeonClaims  map[string]int64 `bson:"dungeon_claims"`
		MailClaims     map[string]int64 `bson:"mail_claims"`
		PurchaseClaims map[string]int64 `bson:"purchase_claims"`
		GuildID        int64            `bson:"guild_id"`
	}
	var doc rollbackDoc
	if err := bson.Unmarshal(raw, &doc); err != nil {
		return err
	}
	d.id = doc.Id
	d.name = doc.Name
	d.level = doc.Level
	d.exp = doc.Exp
	d.gold = doc.Gold
	d.setItemsRawMap(doc.Items)
	d.posX = doc.PosX
	d.posY = doc.PosY
	d.sceneID = doc.SceneID
	d.equipment = equipmentFromBSONDoc(doc.Equipment)
	d.setAttrBaseRawMap(doc.AttrBase)
	d.setAttrFinalRawMap(doc.AttrFinal)
	d.setDungeonClaimsRawMap(doc.DungeonClaims)
	d.setMailClaimsRawMap(doc.MailClaims)
	d.setPurchaseClaimsRawMap(doc.PurchaseClaims)
	d.guildID = doc.GuildID
	d.Init()
	return nil
}

