func (d *PlayerDao) marshalPersistData(mask uint64) []byte {
	_ = mask // full payload is used for inserts and safe fallback.
	doc := bson.M{
		"_id":             d.id,
		"_schema":         PlayerDaoSchemaVersion,
		"name":            d.name,
		"level":           d.level,
		"exp":             d.exp,
		"gold":            d.gold,
		"items":           d.playerDaoItemsRawMap(),
		"pos_x":           d.posX,
		"pos_y":           d.posY,
		"scene_id":        d.sceneID,
		"equipment":       d.equipment.bsonDoc(),
		"attr_base":       d.playerDaoAttrBaseRawMap(),
		"dungeon_claims":  d.playerDaoDungeonClaimsRawMap(),
		"mail_claims":     d.playerDaoMailClaimsRawMap(),
		"purchase_claims": d.playerDaoPurchaseClaimsRawMap(),
		"guild_id":        d.guildID,
	}
	data, err := bson.Marshal(doc)
	if err != nil {
		// The interface has no error slot and a nil payload would be
		// persisted as silent data loss; a marshal failure here is a
		// programming error (unserializable state), so fail loudly and let
		// Data Engine WAL recovery owns the aftermath.
		panic(fmt.Errorf("PlayerDao: marshal persist data: %w", err))
	}
	return data
}

func (d *PlayerDao) persistChangeHasPath(change nest.PersistChange, field string) bool {
	prefix := field + "."
	for path := range change.Set {
		if path == field || len(path) > len(prefix) && path[:len(prefix)] == prefix {
			return true
		}
	}
	for _, path := range change.Unset {
		if path == field || len(path) > len(prefix) && path[:len(prefix)] == prefix {
			return true
		}
	}
	return false
}

func (d *PlayerDao) persistChangePathCovered(change nest.PersistChange, path string) bool {
	for field := range change.FullFields {
		prefix := field + "."
		if path == field || len(path) > len(prefix) && path[:len(prefix)] == prefix {
			return true
		}
	}
	return false
}

func (d *PlayerDao) marshalPersistPatchBSON(change nest.PersistChange) (dataengine.FieldPatch, error) {
	set := make(map[string]any, len(change.Set)+len(change.FullFields))
	if change.Mask&playerDaoFieldName != 0 {
		set["name"] = d.name
	}
	if change.Mask&playerDaoFieldLevel != 0 {
		set["level"] = d.level
	}
	if change.Mask&playerDaoFieldExp != 0 {
		set["exp"] = d.exp
	}
	if change.Mask&playerDaoFieldGold != 0 {
		set["gold"] = d.gold
	}
	if change.Mask&playerDaoFieldItems != 0 {
		_, full := change.FullFields["items"]
		if full || !d.persistChangeHasPath(change, "items") {
			set["items"] = d.playerDaoItemsRawMap()
		}
	}
	if change.Mask&playerDaoFieldPosX != 0 {
		set["pos_x"] = d.posX
	}
	if change.Mask&playerDaoFieldPosY != 0 {
		set["pos_y"] = d.posY
	}
	if change.Mask&playerDaoFieldSceneID != 0 {
		set["scene_id"] = d.sceneID
	}
	if change.Mask&playerDaoFieldEquipment != 0 {
		set["equipment"] = d.equipment.bsonDoc()
	}
	if change.Mask&playerDaoFieldAttrBase != 0 {
		_, full := change.FullFields["attr_base"]
		if full || !d.persistChangeHasPath(change, "attr_base") {
			set["attr_base"] = d.playerDaoAttrBaseRawMap()
		}
	}
	if change.Mask&playerDaoFieldDungeonClaims != 0 {
		_, full := change.FullFields["dungeon_claims"]
		if full || !d.persistChangeHasPath(change, "dungeon_claims") {
			set["dungeon_claims"] = d.playerDaoDungeonClaimsRawMap()
		}
	}
	if change.Mask&playerDaoFieldMailClaims != 0 {
		_, full := change.FullFields["mail_claims"]
		if full || !d.persistChangeHasPath(change, "mail_claims") {
			set["mail_claims"] = d.playerDaoMailClaimsRawMap()
		}
	}
	if change.Mask&playerDaoFieldPurchaseClaims != 0 {
		_, full := change.FullFields["purchase_claims"]
		if full || !d.persistChangeHasPath(change, "purchase_claims") {
			set["purchase_claims"] = d.playerDaoPurchaseClaimsRawMap()
		}
	}
	if change.Mask&playerDaoFieldGuildID != 0 {
		set["guild_id"] = d.guildID
	}
	for path, value := range change.Set {
		if !d.persistChangePathCovered(change, path) {
			set[path] = value
		}
	}
	var raw []byte
	if len(set) != 0 {
		keys := make([]string, 0, len(set))
		for path := range set {
			keys = append(keys, path)
		}
		sort.Strings(keys)
		doc := make(bson.D, 0, len(keys))
		for _, path := range keys {
			doc = append(doc, bson.E{Key: path, Value: set[path]})
		}
		var err error
		raw, err = bson.Marshal(doc)
		if err != nil {
			return dataengine.FieldPatch{}, err
		}
	}
	return dataengine.FieldPatch{SetBSON: raw, Unset: append([]string(nil), change.Unset...)}, nil
}

