func (d *PlayerDao) Unmarshal(raw []byte) error {
	type rawDoc struct {
		Id             int64            `bson:"_id"`
		Name           string           `bson:"name"`
		Level          int32            `bson:"level"`
		Exp            int64            `bson:"exp"`
		Gold           int64            `bson:"gold"`
		Items          map[int64]int32  `bson:"items"`
		PosX           int64            `bson:"pos_x"`
		PosY           int64            `bson:"pos_y"`
		SceneID        int64            `bson:"scene_id"`
		Equipment      equipmentBSONDoc `bson:"equipment"`
		AttrBase       map[int32]int64  `bson:"attr_base"`
		DungeonClaims  map[string]int64 `bson:"dungeon_claims"`
		MailClaims     map[string]int64 `bson:"mail_claims"`
		PurchaseClaims map[string]int64 `bson:"purchase_claims"`
		GuildID        int64            `bson:"guild_id"`
	}
	var dd rawDoc
	if err := bson.Unmarshal(raw, &dd); err != nil {
		return err
	}
	d.id = dd.Id
	d.name = dd.Name
	d.level = dd.Level
	d.exp = dd.Exp
	d.gold = dd.Gold
	d.setItemsRawMap(dd.Items)
	d.posX = dd.PosX
	d.posY = dd.PosY
	d.sceneID = dd.SceneID
	d.equipment = equipmentFromBSONDoc(dd.Equipment)
	d.setAttrBaseRawMap(dd.AttrBase)
	d.setDungeonClaimsRawMap(dd.DungeonClaims)
	d.setMailClaimsRawMap(dd.MailClaims)
	d.setPurchaseClaimsRawMap(dd.PurchaseClaims)
	d.guildID = dd.GuildID
	d.Init()
	return nil
}

// RestorePersisted is the single production hydration path used by the
// Data Engine aggregate repository. Migration and tracker restoration happen
// before the DAO is published through its entity.
func (d *PlayerDao) RestorePersisted(raw []byte, schemaVersion uint32, version uint64) error {
	if schemaVersion > PlayerDaoSchemaVersion {
		return fmt.Errorf("dao PlayerDao: stored schema %d is newer than runtime schema %d", schemaVersion, PlayerDaoSchemaVersion)
	}
	var err error
	if schemaVersion < PlayerDaoSchemaVersion {
		raw, err = d.Migrate(raw, schemaVersion)
		if err != nil {
			return fmt.Errorf("dao PlayerDao: migrate schema %d to %d: %w", schemaVersion, PlayerDaoSchemaVersion, err)
		}
	}
	if err := d.Unmarshal(raw); err != nil {
		return err
	}
	d.tracker.SetVersion(version)
	d.CleanDirty()
	return nil
}

